sql.where:
s.status = '已上课'
AND s.campus_id = #{campusId}
AND s.class_id = #{classId}
AND s.course_id = #{courseId}

  AND COALESCE(NULLIF(s.teacher_name, ''), t.name) = #{teacher}

AND s.lesson_date >= #{start}
AND s.lesson_date <= #{end}
AND COALESCE(x.cnt, 0) > 0
AND COALESCE(x.cnt, 0) = 0

  AND (COALESCE(NULLIF(s.class_name, ''), cg.name) LIKE CONCAT('%', #{keyword}, '%')
    OR COALESCE(NULLIF(s.course_name, ''), co.name) LIKE CONCAT('%', #{keyword}, '%')
    OR COALESCE(NULLIF(s.teacher_name, ''), t.name) LIKE CONCAT('%', #{keyword}, '%')
    OR s.topic LIKE CONCAT('%', #{keyword}, '%'))
